[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path, [string]$Emulador = '', [switch]$Verificar, [switch]$SomenteAplicar, [switch]$TestarBanco)
$ErrorActionPreference = 'Stop'
if ($TestarBanco -and -not $Emulador) { throw 'Informe -Emulador para executar os testes nativos.' }
$Projeto = (Resolve-Path -LiteralPath $Projeto).Path
$localFile = Join-Path $Projeto 'local.properties'
$hadLocalProperties = Test-Path -LiteralPath $localFile
$localBefore = if ($hadLocalProperties) { [IO.File]::ReadAllText($localFile) } else { '' }
$versionMatch = [regex]::Matches($localBefore, '(?m)^[ \t]*APP_VERSION_CODE[ \t]*[=:][ \t]*(\d+)[ \t]*$')
if ($versionMatch.Count -gt 0 -and [long]$versionMatch[$versionMatch.Count - 1].Groups[1].Value -gt 10) { throw 'O projeto ja possui codigo de versao superior a 10. Nenhuma alteracao aplicada.' }
function Set-LocalVersion([string]$text, [string]$key, [string]$value) {
    $pattern = '(?m)^[ \t]*' + [regex]::Escape($key) + '(?:[ \t]*[=:]|[ \t]+)[^\r\n]*(?:\r?\n|$)'
    $text = [regex]::Replace($text, $pattern, '')
    if ($text.Length -gt 0 -and -not $text.EndsWith("`n")) { $text += "`r`n" }
    return $text + $key + '=' + $value + "`r`n"
}

if (-not (Test-Path -LiteralPath (Join-Path $Projeto 'gradlew.bat'))) { throw 'Informe -Projeto com a raiz do projeto Android.' }
$entries = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) | ConvertFrom-Json
foreach ($entry in $entries) {
    $target = Join-Path $Projeto $entry.path
    if (-not (Test-Path -LiteralPath $target)) {
        if ($entry.allowMissing) { continue }
        throw "Arquivo ausente: $($entry.path)"
    }
    if ($entry.allowed -notcontains (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToLowerInvariant()) {
        throw "Arquivo diferente da versao enviada neste chat: $($entry.path). Nenhuma alteracao aplicada."
    }
    if (([BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash([Convert]::FromBase64String($entry.data))).Replace('-','').ToLowerInvariant()) -ne $entry.sha) { throw 'Pacote danificado.' }
}
if ($Verificar) { Write-Host 'OK: os arquivos sao compativeis. Nenhuma alteracao aplicada.'; return }
$backup = Join-Path $Projeto ('.navigation-backups\versao-1.8-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
New-Item -ItemType Directory -Path $backup -Force | Out-Null
if ($hadLocalProperties) { Copy-Item -LiteralPath $localFile -Destination (Join-Path $backup 'local.properties') }
foreach ($entry in $entries) {
    $saved = Join-Path $backup $entry.path
    New-Item -ItemType Directory -Path (Split-Path $saved -Parent) -Force | Out-Null
    $target = Join-Path $Projeto $entry.path
    if (Test-Path -LiteralPath $target) { Copy-Item -LiteralPath $target -Destination $saved }
}
try {
    foreach ($entry in $entries) {
        $target = Join-Path $Projeto $entry.path
        New-Item -ItemType Directory -Path (Split-Path $target -Parent) -Force | Out-Null
        [IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($entry.data))
    }
    $localAfter = Set-LocalVersion $localBefore 'APP_VERSION_CODE' '10'
    $localAfter = Set-LocalVersion $localAfter 'APP_VERSION_NAME' '1.8'
    [IO.File]::WriteAllText($localFile, $localAfter, [Text.UTF8Encoding]::new($false))
} catch {
    if ($hadLocalProperties) { Copy-Item -LiteralPath (Join-Path $backup 'local.properties') -Destination $localFile -Force }
    elseif (Test-Path -LiteralPath $localFile) { Remove-Item -LiteralPath $localFile }

    foreach ($entry in $entries) {
        $saved = Join-Path $backup $entry.path
        $target = Join-Path $Projeto $entry.path
        if (Test-Path -LiteralPath $saved) { Copy-Item -LiteralPath $saved -Destination $target -Force }
        elseif ($entry.allowMissing -and (Test-Path -LiteralPath $target)) { Remove-Item -LiteralPath $target }
    }
    throw
}
Write-Host "Aplicado. Backup: $backup"
if ($SomenteAplicar) { return }
Push-Location $Projeto
try {
    if ($TestarBanco) { & .\gradlew.bat --no-daemon --max-workers=2 assembleDebug assembleDebugAndroidTest }
    else { & .\gradlew.bat --no-daemon --max-workers=2 assembleDebug }
    if ($LASTEXITCODE -ne 0) { throw 'Compilacao falhou. Nenhum APK foi instalado.' }
    if ($Emulador) {
        $adb = Join-Path $env:LOCALAPPDATA 'Android\Sdk\platform-tools\adb.exe'
        if (-not (Test-Path -LiteralPath $adb)) { throw 'ADB nao encontrado. Compile e instale pelo Android Studio.' }
        $m = Get-Content -LiteralPath '.\app\build\outputs\apk\debug\output-metadata.json' -Raw | ConvertFrom-Json
        if ($m.applicationId -ne 'br.com.flaviotorres.iptvpremium') { throw 'APK de outro aplicativo. Instalacao cancelada.' }
        if (@($m.elements | Where-Object { $_.versionCode -ne 10 -or $_.versionName -ne '1.8' }).Count -gt 0) { throw 'A compilacao nao gerou versao 1.8 codigo 10. Nenhum APK foi instalado.' }
        $abis = (& $adb -s $Emulador shell getprop ro.product.cpu.abilist).Trim().Split(',')
        if ($LASTEXITCODE -ne 0) { throw 'Nao foi possivel consultar o dispositivo.' }
        $chosen = @($m.elements | Where-Object { @($_.filters).Count -eq 0 }) | Select-Object -First 1
        if (-not $chosen) {
            foreach ($abi in $abis) {
                $chosen = $m.elements | Where-Object { @($_.filters | Where-Object { $_.filterType -eq 'ABI' -and $_.value -eq $abi }).Count -gt 0 } | Select-Object -First 1
                if ($chosen) { break }
            }
        }
        if (-not $chosen) { throw 'Nenhum APK compativel com o dispositivo.' }
        $apkRoot = [IO.Path]::GetFullPath((Join-Path $Projeto 'app\build\outputs\apk\debug'))
        $apk = [IO.Path]::GetFullPath((Join-Path $apkRoot $chosen.outputFile))
        if ((Split-Path $apk -Parent) -ne $apkRoot -or -not (Test-Path -LiteralPath $apk)) { throw 'Saida de APK invalida.' }
        & $adb -s $Emulador install -r $apk
        if ($LASTEXITCODE -ne 0) { throw 'Instalacao falhou; nao desinstale nem limpe dados.' }
        if ($TestarBanco) {
            $testRoot = Join-Path $Projeto 'app\build\outputs\apk\androidTest\debug'
            $testMeta = Get-Content -LiteralPath (Join-Path $testRoot 'output-metadata.json') -Raw | ConvertFrom-Json
            if ($testMeta.applicationId -ne 'br.com.flaviotorres.iptvpremium.test' -or @($testMeta.elements).Count -ne 1) { throw 'APK de teste inesperado.' }
            $testApk = [IO.Path]::GetFullPath((Join-Path $testRoot $testMeta.elements[0].outputFile))
            if ((Split-Path $testApk -Parent) -ne [IO.Path]::GetFullPath($testRoot)) { throw 'Caminho de teste invalido.' }
            & $adb -s $Emulador install -r -t $testApk
            if ($LASTEXITCODE -ne 0) { throw 'Falha ao instalar os testes.' }
            $testLog = Join-Path $Projeto 'diagnostico-versao-1.8-testes.txt'
            $classes = 'br.com.flaviotorres.iptvpremium.data.cache.ImportTuningPolicyDeviceTest,br.com.flaviotorres.iptvpremium.data.cache.ImportBatchDeviceTest,br.com.flaviotorres.iptvpremium.data.cache.ImportTuningDeviceTest,br.com.flaviotorres.iptvpremium.data.sync.ImportAlternativesDeviceTest,br.com.flaviotorres.iptvpremium.data.sync.ImportAlternativesRoomDeviceTest,br.com.flaviotorres.iptvpremium.core.device.PortalPlaylistCodecDeviceTest,br.com.flaviotorres.iptvpremium.core.device.AlternativeStorageDeviceTest'
            $result = & $adb -s $Emulador shell am instrument -w -e class $classes 'br.com.flaviotorres.iptvpremium.test/androidx.test.runner.AndroidJUnitRunner' 2>&1
            $testExit = $LASTEXITCODE
            $result | Out-File -FilePath $testLog -Encoding utf8
            $result | Write-Host
            $textResult = $result | Out-String
            if ($testExit -ne 0 -or $textResult -notmatch 'OK \(27 tests\)' -or $textResult -match 'FAILURES!!!|INSTRUMENTATION_FAILED|Process crashed') {
                throw "Teste de importacao nao aprovado. Diagnostico: $testLog. O app instalado foi preservado."
            }
        }
    }
} finally { Pop-Location }
Write-Host 'Concluido: versao 1.8 codigo 10, Xtream 250 e M3U 2000 por padrao. Listas e historico preservados.'


if ($Emulador -and $TestarBanco) {
    & (Join-Path $Projeto 'entregas-locais/perfis-importacao-1.07/Testar-Perfil-Importacao-1.07.ps1') -Perfil PADRAO -Dispositivo $Emulador -PastaSaida $Projeto -SomenteConfigurar
    Write-Host 'Padrao da versao 1.8 confirmado: Xtream 250, M3U 2000. Abra o app normalmente.'
}
